query:
SELECT ?code ?lang ?label WHERE {
  VALUES ?code { "IN-AN" "IN-AP" "IN-AR" "IN-AS" "IN-BR" "IN-CG" "IN-CH" "IN-DH" "IN-DL" "IN-GA" "IN-GJ" "IN-HP" "IN-HR" "IN-JH" "IN-JK" "IN-KA" "IN-KL" "IN-LA" "IN-LD" "IN-MH" "IN-ML" "IN-MN" "IN-MP" "IN-MZ" "IN-NL" "IN-OD" "IN-PB" "IN-PY" "IN-RJ" "IN-SK" "IN-TN" "IN-TR" "IN-TS" "IN-UK" "IN-UP" "IN-WB" }
  ?item wdt:P300 ?code .
  FILTER NOT EXISTS { ?item wdt:P576 ?dissolved }
  ?item rdfs:label ?label . BIND(LANG(?label) AS ?lang)
  FILTER(?lang IN ("en", "es", "fr", "pt", "de", "it", "ro", "ru", "ar", "hi", "zh-hans", "zh-cn", "zh"))
}
